// display-only: the simplest component
function Hello() {
  return <h1>Hello!</h1>;
}

// display-only: expressions in curly braces
const name = 'Roli';
return <h1>Hello, {name}!</h1>;
return <p>2 + 2 = {2 + 2}</p>;

// display-only: capital matters
function Greeting() {   // a component
  return <h1>Hi!</h1>;
}
// <greeting /> would be treated as an HTML tag — broken

// display-only: passing props
function Greeting(props) {
  return <h1>Hello, {props.name}!</h1>;
}
// <Greeting name='Roli' /> → Hello, Roli!
// <Greeting name='Ada' />  → Hello, Ada!

// display-only: destructuring props
function Greeting({ name, mood }) {
  return <h1>{mood}, {name}!</h1>;
}
// <Greeting name='Roli' mood='Morning' />

// display-only: one parent per return
function Card() {
  return (
    <div>
      <h2>Title</h2>
      <p>Body text</p>
    </div>
  );
}

// display-only: nesting components
function App() {
  return (
    <div>
      <Header />
      <Greeting name='Roli' />
    </div>
  );
}
